SELECT 'MrpManufacturingBatch' AS t, status::text AS status, count(*) FROM "MrpManufacturingBatch" GROUP BY 1,2 UNION ALL SELECT 'FactoryProductionBatch', status::text, count(*) FROM "FactoryProductionBatch" GROUP BY 1,2 UNION ALL SELECT 'FactoryPlanningBatch', status::text, count(*) FROM "FactoryPlanningBatch" GROUP BY 1,2 UNION ALL SELECT 'FactoryPlanningBooth', status::text, count(*) FROM "FactoryPlanningBooth" GROUP BY 1,2 UNION ALL SELECT 'BoothUnit', status::text, count(*) FROM "BoothUnit" GROUP BY 1,2 UNION ALL SELECT 'InventoryUnit', status::text, count(*) FROM "InventoryUnit" GROUP BY 1,2 UNION ALL SELECT 'FactoryProductionBoothUnit', status, count(*) FROM "FactoryProductionBoothUnit" GROUP BY 1,2 ORDER BY 1,2
